for (const item of items) {
    // 1. Detección de Fallback o Error de Proveedor Externo
    const rawOutput = item.json.output;
    const hasError = item.json.error || 
                     item.json.is_fallback_triggered ||
                     (typeof rawOutput === 'string' && (rawOutput.includes('503') || rawOutput.includes('Service Unavailable') || rawOutput.includes('high demand')));

    let sourceText = "";
    if (hasError) {
        sourceText = "En este momento nuestros servicios de consulta general presentan alta demanda. Si deseas consultar saldo, planes o recargas de Movilnet, escribe 'Saldo' o 'Planes'.";
    } else {
        sourceText = item.json.output || item.json.Content || "En este momento nuestros servicios de consulta general presentan alta demanda. Si deseas consultar saldo, planes o recargas de Movilnet, escribe 'Saldo' o 'Planes'.";
    }

    if (sourceText && typeof sourceText !== 'string') {
        sourceText = JSON.stringify(sourceText);
    }

    let cleanText = sourceText;

    // 2. Normalizar saltos de línea (Windows \r\n -> \n)
    cleanText = cleanText.replace(/\r\n/g, '\n');

    // 3. Limpieza de Markdown conservando la estructura de lista
    cleanText = cleanText.replace(/\*\*\*([^*]+)\*\*\*/g, '$1');
    cleanText = cleanText.replace(/\*\*([^*]+)\*\*/g, '$1');
    cleanText = cleanText.replace(/\_([^_]+)\_/g, '$1');
    cleanText = cleanText.replace(/\*([^*]+)\*/g, '$1');
    cleanText = cleanText.replace(/^#+\s?/gm, '');

    // 4. Limpieza de espacios manteniendo la separación de viñetas y saltos
    cleanText = cleanText.replace(/[ \t]+/g, ' ');
    cleanText = cleanText.replace(/\n\s+/g, '\n');
    cleanText = cleanText.trim();

    // 5. Fallback por si el resultado es vacío
    if (!cleanText || cleanText === "" || cleanText === "undefined") {
        cleanText = "En este momento nuestros servicios de consulta general presentan alta demanda. Si deseas consultar saldo, planes o recargas de Movilnet, escribe 'Saldo' o 'Planes'.";
    }

    // 6. Cadencia de Mecanografía Humana Adaptativa Anti-Baneo Meta
    // Emulación de escritura natural: delay proporcional a longitud con jitter aleatorio
    const charCount = cleanText.length;
    let baseDelay = 800; // ms base para mensajes cortos (< 50 caracteres)
    if (charCount > 250) {
        baseDelay = 1800;
    } else if (charCount > 100) {
        baseDelay = 1400;
    } else if (charCount > 50) {
        baseDelay = 1100;
    }
    // Jitter estocástico humano (entre -120ms y +180ms) para evitar entropía constante
    const jitter = Math.floor(Math.random() * 300) - 120;
    const dynamicDelay = Math.min(Math.max(baseDelay + jitter, 650), 2200);
    item.json.human_delay_ms = dynamicDelay;

    // Guardar en la propiedad de salida
    item.json.final_text = cleanText;
}

return items;

for (const item of items) {
  // Asegúrate de que la propiedad 'output' existe y es una cadena de texto
  if (item.json.output && typeof item.json.output === 'string') {
    let cleanText = item.json.output;

    // 1. Reemplazar saltos de línea y retornos de carro
    cleanText = cleanText.replace(/(\n|\r)/g, ' ');

    // 2. Eliminar negritas (**) y cursivas (_) o (***)
    cleanText = cleanText.replace(/\*\*[^*]+\*\*/g, (match) => match.replace(/\*\*/g, ''));
    cleanText = cleanText.replace(/_[^_]+_/g, (match) => match.replace(/_/g, ''));
    cleanText = cleanText.replace(/\*\*\*[^*]+\*\*\*/g, (match) => match.replace(/\*\*\*/g, ''));

    // 3. Eliminar otros marcadores de Markdown (por ejemplo, títulos #, listas -, etc.)
    cleanText = cleanText.replace(/#+\s?/g, '');
    cleanText = cleanText.replace(/-\s/g, '');
     cleanText = cleanText.replace(/"/g, '');

    // 4. Recortar espacios en blanco al inicio y al final
    cleanText = cleanText.trim();

     // Asigna el texto limpio a una nueva propiedad
    item.json.final_text = cleanText;
  }
}

return items;

