// 1. Obtenemos el mensaje original de forma segura usando .first()
const mensaje = $('Chat').first().json.Content || '';

const limpio = mensaje
  .toLowerCase()
  .replace(/\./g, '')
  .replace(',', '.');

// 2. Buscamos el monto en dólares en el texto
const match = limpio.match(/(?:\$|usd|dolares?|dolar)\s*(\d+(?:\.\d+)?)/) ||
              limpio.match(/(\d+(?:\.\d+)?)\s*(?:\$|usd|dolares?|dolar)/);

if (!match) {
  return {
    json: {
      Content: 'Indica el monto en dólares.'
    }
  };
}

const montoUsd = Number(match[1]);
// $json aquí corresponde a la respuesta del nodo "BCV oficial - Conversión"
const tasa = Number($json.promedio ?? $json.venta ?? $json.compra);

if (!Number.isFinite(montoUsd) || !Number.isFinite(tasa)) {
  return {
    json: {
      Content: 'No pude calcular la conversión.'
    }
  };
}

const totalBs = montoUsd * tasa;

// 3. Obtenemos el nombre del usuario de forma segura usando .first()
const nombre = $('Edit Fields').first().json.body?.data?.pushName ?? '';

return {
  json: {
    Content: `${nombre ? `${nombre}, ` : ''}$${montoUsd.toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} equivalen a Bs. ${totalBs.toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}.`
  }
};

const oficial = Number($json.tasa_bcv);
const paralela = Number($json.tasa_paralela);

if (!Number.isFinite(oficial) || !Number.isFinite(paralela) || oficial <= 0) {
  return {
    json: {
      Content: 'No pude obtener ambas tasas para calcular el diferencial.'
    }
  };
}

const diferencial = paralela / oficial;
const porcentaje = (diferencial - 1) * 100;

return {
  json: {
    Content:
      `Diferencial: ${porcentaje.toLocaleString('es-VE', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      })}%. ` +
      `Paralela: Bs. ${paralela.toLocaleString('es-VE', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      })}; ` +
      `BCV: Bs. ${oficial.toLocaleString('es-VE', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
